def estimate_budget_allocation(total_budget):
    explore = int(0.4 * total_budget)
    exploit = int(0.4 * total_budget)
    combine = total_budget - explore - exploit   # absorb rounding
    return {
        'exploration': explore,
        'exploitation': exploit,
        'combination': combine,
    }

allocation = estimate_budget_allocation(1000)
for phase, n in allocation.items():
    print(f"{phase:12}: {n:4d} queries")
# exploration : 400  |  exploitation: 400  |  combination : 200
